-- Hyprland configuration — kpango (Threadripper 3990X / RTX 2070 SUPER / Wayland)
-- requires: hyprland hypridle swww grim slurp mako wofi waybar fcitx5

-- ══════════════════════════════════════════════════════════════════════════════
-- ENVIRONMENT — NVIDIA RTX 2070 SUPER + Wayland
-- ══════════════════════════════════════════════════════════════════════════════

-- NVIDIA Wayland backend
-- Generated by hyprlang2lua + manual TODO resolution. All directives reviewed.

hl.env("LIBVA_DRIVER_NAME", "nvidia")
hl.env("GBM_BACKEND", "nvidia-drm")
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
hl.env("NVD_BACKEND", "direct")
hl.env("__GL_GSYNC_ALLOWED", "1")

-- Wayland session
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")

-- Electron apps (Slack, Discord, VSCode) → Wayland ネイティブ
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "wayland")

-- Qt → Wayland ネイティブ
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")

-- GTK (GTK4 は GDK_BACKEND のみ参照、GTK_BACKEND は GTK3 レガシー)
hl.env("GDK_BACKEND", "wayland,x11")
hl.env("GTK_THEME", "Adwaita:dark")

-- Firefox / Thunderbird
hl.env("MOZ_ENABLE_WAYLAND", "1")

-- SDL / libinput
-- wayland,x11 順でフォールバック（ゲームの互換性確保）
hl.env("SDL_VIDEODRIVER", "wayland,x11")
hl.env("CLUTTER_BACKEND", "wayland")

-- NVIDIA パフォーマンス
-- フレームキューを 1 に絞りレンダリングレイテンシを削減（NVIDIA プロプライエタリ限定）
hl.env("__GL_MaxFramesAllowed", "1")
-- シェーダーをディスクキャッシュして初回起動時のスタッターを低減
hl.env("__GL_SHADER_DISK_CACHE", "1")
hl.env("__GL_SHADER_DISK_CACHE_PATH", "$HOME/.cache/nv-shader-cache")

-- GBM modifier negotiation を無効化（NVIDIA 環境での黒画面回避）
hl.env("AQ_NO_MODIFIERS", "1")

-- Cursor
hl.env("XCURSOR_THEME", "Adwaita")
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

-- ══════════════════════════════════════════════════════════════════════════════
-- MONITORS
-- ══════════════════════════════════════════════════════════════════════════════
-- `hyprctl monitors` で実機の出力名・解像度を確認して調整すること。
-- kanshi は Hyprland 非対応のため monitor= で直接管理する。

-- Dell U4919DW (DP-1, DP-3): EDID 実測 10bpc 宣言確認済み → bitdepth 10 有効
-- LG ULTRAWIDE (HDMI-A-1): EDID bpc 未定義 (HDMI 8bpc デフォルト) → 10bit 強制は不安定のため見送り
hl.monitor({
    output = "eDP-1",
    mode = "preferred",
    position = "auto",
    scale = "1",
})

hl.monitor({
    output = "DP-1",
    mode = "preferred",
    position = "auto",
    scale = "1",
    bitdepth = 10,
})

hl.monitor({
    output = "DP-2",
    mode = "preferred",
    position = "auto",
    scale = "1",
})

hl.monitor({
    output = "DP-3",
    mode = "preferred",
    position = "auto",
    scale = "1",
    bitdepth = 10,
})

hl.monitor({
    output = "DP-4",
    mode = "preferred",
    position = "auto",
    scale = "1",
})

hl.monitor({
    output = "HDMI-A-1",
    mode = "preferred",
    position = "auto",
    scale = "1",
})

hl.monitor({
    output = "",
    mode = "preferred",
    position = "auto",
    scale = "1",
})

