hl.config({
    render = {
        -- explicit_sync / explicit_sync_kms は v0.50 で削除済み（常時 ON のためオプション不要）
        direct_scanout = false, -- NVIDIA では false 推奨（フルスクリーン最適化は VRR で行う）
