hl.on("hyprland.start", function()
    hl.exec_cmd("systemctl --user import-environment DISPLAY WAYLAND_DISPLAY HYPRLAND_INSTANCE_SIGNATURE XDG_CURRENT_DESKTOP")
    hl.exec_cmd("dbus-update-activation-environment --systemd DISPLAY WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE")
    hl.exec_cmd("sleep 0.5 && /usr/lib/xdg-desktop-portal-hyprland")
    hl.exec_cmd("sleep 1.5 && /usr/lib/xdg-desktop-portal --replace")
    hl.exec_cmd("waybar --config $HOME/.config/waybar/config-hyprland.json --style $HOME/.config/waybar/style.css")
    hl.exec_cmd("mako")
    hl.exec_cmd("fcitx5 -rd")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("systemctl --user start --no-block hyprland-session.target")
    hl.exec_cmd("swww-daemon")
    -- config.reloaded は hyprland.start より前に発火するため初回壁紙は ここで設定する
    hl.exec_cmd("sleep 0.5 && swww img \"$(find -L $HOME/.wallpapers -type f ! -path '*/.git/*' ! -name 'Makefile' ! -name '*.go' ! -name 'go.mod' ! -name 'go.sum' | shuf -n1)\" --transition-type wipe --transition-duration 1.5")
    hl.exec_cmd(term)
end)

hl.on("config.reloaded", function()
    -- reload 時のみ: hyprland.start 後は swww-daemon が起動済みのため即時実行可
    hl.exec_cmd("swww img \"$(find -L $HOME/.wallpapers -type f ! -path '*/.git/*' ! -name 'Makefile' ! -name '*.go' ! -name 'go.mod' ! -name 'go.sum' | shuf -n1)\" --transition-type wipe --transition-duration 1.5")
end)

